import { EXERCISES, SESSIONS, RESOURCES, MUSCLE_GROUPS, GROUP_IDS, CARDIO_CATEGORIES } from './data.js';
import { iso, parse, move, monday, days, niceDate, longDate, DAYS, buildWeek, weeklyStats, isStrength, isCardio, delta } from './planner.mjs';

const STORE = 'gymos_local_v2';
const $ = s => document.querySelector(s);
const asText = v => String(v ?? '');
const esc = v => asText(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today = () => iso(new Date());
const safeNumber = (x, fallback=0) => { const v=Number(x);return Number.isFinite(v)?v:fallback; };
const initial = () => ({version:1,settings:{nickname:'Khai Trí',height:170,startWeight:70,targetWeight:68,experience:'beginner',theme:'lime'},logs:{},skips:{},drafts:{},weights:[]});
const THEMES={lime:{label:'Xanh lá · đen',color:'#c8f376'},purple:{label:'Tím · đen',color:'#b48cff'},orange:{label:'Cam · đen',color:'#ff9f43'},cyan:{label:'Xanh ngọc · đen',color:'#5de1d0'}};
let state;
try {const loaded=JSON.parse(localStorage.getItem(STORE) || 'null'); state = loaded && typeof loaded === 'object' ? {...initial(),...loaded,settings:{...initial().settings,...(loaded.settings||{})},logs:loaded.logs||{},skips:loaded.skips||{},drafts:loaded.drafts||{},weights:Array.isArray(loaded.weights)?loaded.weights:[]} : initial(); if(!state.settings.nickname || state.settings.nickname==='Khải Trí' || state.settings.nickname==='Khai Tri') state.settings.nickname='Khai Trí';} catch {state=initial();}
let route='home', weekStart=monday(today()), exerciseFilter='all', exerciseQuery='', cardioFilter='all', selectedExercise=null, workoutDate=null, workoutType=null, timerStart=null, timerLeft=0, timerHandle=null, promptModal=null;
const sessionName = type => SESSIONS[type]?.name || 'Nghỉ / đi bộ nhẹ';
const getGroup = x => x?.groupId || (Object.entries({chest:'Ngực',back:'Lưng',shoulders:'Vai',legs:'Chân',glutes:'Mông',biceps:'Tay trước',triceps:'Tay sau',core:'Core'}).find(([,name])=>(x?.group||'').includes(name))?.[0]||'other');
const muscleName = id => id==='cardio'?'Tim mạch':MUSCLE_GROUPS.find(g=>g.id===id)?.name || 'Khác';
const getPlan = start => buildWeek(start,today(),state);
const save = () => {try{localStorage.setItem(STORE,JSON.stringify(state));return true;}catch{toast('Không lưu được dữ liệu trên thiết bị. Hãy xuất bản sao lưu.');return false;}};
const niceDay = d => DAYS[(parse(d).getDay()+6)%7];
const n = x => Number(x || 0);
const cardioExercises = () => Object.entries(EXERCISES).filter(([,x])=>x.group==='Tim mạch');
const moderateCardio = x => !['Nâng cao','Mạnh'].includes(x.difficulty)&&x.intensity!=='Mạnh';
const PREVIEW_ASSETS={press:'./assets/preview-press.png',pull:'./assets/preview-pull.png',shoulders:'./assets/preview-shoulders.png',arms:'./assets/preview-arms.png',legs:'./assets/preview-legs.png',hinge:'./assets/preview-hinge.png',core:'./assets/preview-core.png',cardioMachine:'./assets/preview-cardio-machine.png',cardioCircuit:'./assets/preview-cardio-circuit.png'};
function previewKey(x){
 const group=getGroup(x),pattern=x?.movementPattern||'';
 if(x?.group==='Tim mạch') return x?.cardioCategory==='machine'?'cardioMachine':'cardioCircuit';
 if(['squat','lunge'].includes(pattern)) return 'legs';
 if(pattern==='hinge') return 'hinge';
 if(['press','fly'].includes(pattern)) return group==='shoulders'?'shoulders':'press';
 if(pattern==='pull') return 'pull';
 if(['raise'].includes(pattern)) return group==='biceps'||group==='triceps'?'arms':'shoulders';
 if(['curl','extension'].includes(pattern)) return 'arms';
 if(group==='core' || ['hold','anti-rotation','rotation','flexion'].includes(pattern)) return 'core';
 if(['legs','glutes'].includes(group)) return 'legs';
 if(['biceps','triceps'].includes(group)) return 'arms';
 if(group==='back') return 'pull';
 if(group==='shoulders') return 'shoulders';
 return 'press';
}
function previewSrc(x){return PREVIEW_ASSETS[previewKey(x)]||PREVIEW_ASSETS.press;}
function previewImg(x,cls='exercise-cover',label=''){return `<div class="${cls}"><img src="${previewSrc(x)}" alt="${esc(label||x?.vi||'Bài tập')}" loading="lazy" decoding="async"></div>`;}
function breathingBullets(x){
 if(!x) return [];
 if(x.group==='Tim mạch') return [x.breath,'Giữ nhịp thở đều và thư giãn vai, hàm, cổ.','Dùng talk test: vẫn nên nói được câu đầy đủ; nếu không, hãy giảm cường độ.','Cuối buổi thả lỏng 3–5 phút để nhịp tim xuống dần.'];
 return [x.breath,'Trước mỗi rep: hít ngắn và gồng bụng nhẹ để ổn định thân.','Trong rep: không nín thở quá lâu; nếu nặng, hãy nhả hơi chậm ở pha gắng sức.','Sau rep: lấy lại nhịp thở rồi mới bắt đầu rep tiếp theo.'];
}
function breathingMarkup(x){return `<ul class="breath-list">${breathingBullets(x).map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`;}
function movementLabel(x){const map={press:'Đẩy',pull:'Kéo',fly:'Ép / dang',raise:'Nâng',curl:'Cuốn',extension:'Duỗi',hinge:'Hip hinge',squat:'Squat',lunge:'Lunge',hold:'Giữ core'};return x?.group==='Tim mạch'?(x?.cardioCategory==='machine'?'Cardio bằng máy':'Circuit / cardio động tác'):map[x?.movementPattern]||'Tập cơ';}
const weekPhase = d => { const cardioDates=Object.entries(state.logs).filter(([date,log])=>date<=d&&log?.completed&&isCardio(log.type)).map(([date])=>date).sort();return cardioDates.length >= 3 && (parse(d)-parse(cardioDates[0]))>=14*86400000 ? 2 : 1; };
function applyTheme(theme){const chosen=THEMES[theme]?theme:'lime';document.body.dataset.theme=chosen;document.querySelector('meta[name="theme-color"]')?.setAttribute('content',getComputedStyle(document.documentElement).getPropertyValue('--bg').trim()||'#0b1116');}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>el.classList.remove('show'),3300);}
function setRoute(next, params={}){route=next;if(params.week)weekStart=params.week;if(params.exercise)selectedExercise=params.exercise;if(params.date)workoutDate=params.date;if(params.type)workoutType=params.type;render();scrollTo({top:0,behavior:'instant'});}
function btn(label,action,className='btn',attrs=''){return `<button type="button" class="${className}" data-action="${esc(action)}" ${attrs}>${label}</button>`;}
function sessionPill(type){return type==='A'?'<span class="chip green">Full Body A</span>':type==='B'?'<span class="chip purple">Full Body B</span>':isCardio(type)?`<span class="chip aqua">${esc(sessionName(type))}</span>`:SESSIONS[type]?`<span class="chip green">${esc(SESSIONS[type].name)}</span>`:'<span class="chip dim">Nghỉ</span>';}
function dateTitle(d){return `${niceDay(d)}, ${niceDate(d)}`;}
function title(eyebrow, heading, description, extra=''){return `<div class="head-row"><div><div class="eyebrow">${eyebrow}</div><h1 style="margin-top:8px">${heading}</h1><p>${description}</p></div>${extra}</div>`;}
function healthNote(){return `<div class="callout health-warning"><b>⚕ Lưu ý an toàn khi bắt đầu</b>Nếu có tiền sử bệnh tim, rối loạn nhịp, hen suyễn hoặc triệu chứng lúc gắng sức, nên hỏi bác sĩ trước khi tăng cường độ. Bắt đầu ở mức vừa sức, không nín thở. Dừng tập và tìm hỗ trợ y tế nếu đau ngực, choáng/ngất, khó thở bất thường hoặc đánh trống ngực kéo dài. Không đưa thông tin y tế cá nhân lên GitHub.</div>`;}
function walkInfo(full=true){const p=weekPhase(today());return `<div class="walk-guide"><div class="eyebrow aqua">TREADMILL · TUẦN ${p===1?'1–2':'3–4+'}</div><h3 style="margin:7px 0 12px">Đi bộ, không cần chạy</h3><div class="walk-steps"><div><b>05'</b><span>Khởi động</span><strong>3,0–3,5 km/h</strong><small>Dốc 0%</small></div><div><b>${p===1?'10–15':'15–20'}'</b><span>Đi bộ chính</span><strong>${p===1?'3,8–4,5':'4,2–5,0'} km/h</strong><small>Dốc ${p===1?'0–1':'1–2'}%</small></div><div><b>05'</b><span>Thả lỏng</span><strong>2,8–3,2 km/h</strong><small>Dốc 0%</small></div></div><p class="muted-sm" style="margin-top:12px">Tốc độ mang tính gợi ý. Chỉ tăng khi đi vững, không đau, còn nói được câu đầy đủ. Giảm tốc/dốc ngay nếu cảm thấy gắng sức hơn mức vừa.</p>${full?`<p class="muted-sm" style="margin-top:7px">Sau khi đã quen, ưu tiên tăng thời lượng trước, rồi mới thử tăng tốc độ hoặc dốc (mỗi lần chỉ đổi một yếu tố).</p>`:''}</div>`;}
function weekdayTile(entry){const isToday=entry.date===today(),sess=SESSIONS[entry.type];const icon=entry.kind==='done'?'✓':entry.kind==='skipped'?'×':sess?.icon || '·';const label=entry.kind==='done'?'Đã tập':entry.kind==='skipped'?'Bỏ buổi':entry.kind==='past'?'Đã qua':sess?isCardio(entry.type)?'Cardio':entry.type==='A'||entry.type==='B'?`Buổi ${entry.type}`:sess.name:'Nghỉ';return `<button class="day-tile ${isToday?'today':''} ${entry.kind==='done'?'completed':''} ${entry.kind==='skipped'?'skipped':''}" data-action="day" data-date="${entry.date}" title="${dateTitle(entry.date)} – ${label}"><span class="weekday">${niceDay(entry.date).replace('Thứ ','T')}</span><span class="daynum">${parse(entry.date).getDate()}</span><span class="day-icon">${icon}</span><span class="day-label ${entry.kind==='done'?'done':entry.kind==='skipped'?'skip':''}">${label}</span></button>`;}
function weekStrip(plan){return `<div class="week-strip">${plan.days.map(weekdayTile).join('')}</div><p class="week-caption">Chạm vào một ngày để bắt đầu tập, bỏ buổi hoặc sửa lịch. Lịch sẽ tự phân bổ lại các buổi chưa tập.</p>`;}
function sessionCard(day){const s=SESSIONS[day.type];if(!s)return '';return `<div class="session-card"><div class="session-symbol ${s.accent}">${s.icon}</div><div class="session-info"><strong>${esc(s.name)}</strong><p>${esc(s.description)}</p><div class="session-meta">${dateTitle(day.date)} · ${s.time}</div></div>${btn('Xem buổi tập ↗','open-workout','btn small primary',`data-date="${day.date}" data-type="${day.type}"`)}</div>`;}
function weeklyTrainingData(plan){
 const entries=Object.entries(state.logs).filter(([date,log])=>date>=plan.start&&date<=plan.end&&log?.completed);
 const cardio=entries.filter(([,log])=>isCardio(log.type));
 const sets=entries.reduce((sum,[,log])=>sum+Object.values(log.exercises||{}).reduce((subtotal,item)=>subtotal+(item.sets||[]).filter(set=>set.done).length,0),0);
 const cardioMinutes=cardio.reduce((sum,[,log])=>sum+(Number(log.minutes)||0),0);
 const allMinutes=entries.reduce((sum,[,log])=>sum+(Number(log.minutes)||0),0);
 return {entries,sets,cardioMinutes,allMinutes};
}
function attendanceTrend(start){
 const weeks=Array.from({length:8},(_,i)=>{
  const ws=move(start,(i-7)*7),we=move(ws,6);
  const count=Object.entries(state.logs).filter(([date,log])=>date>=ws&&date<=we&&log?.completed).length;
  return {start:ws,count};
 });
 const top=Math.max(3,...weeks.map(w=>w.count));
 return `<div class="trend-chart" role="img" aria-label="Biểu đồ 8 tuần gần nhất, số buổi tập đã hoàn thành">${weeks.map((w,i)=>`<div class="trend-column" title="Tuần ${niceDate(w.start)}: ${w.count} buổi"><span class="trend-count">${w.count}</span><div class="trend-bartrack"><div class="trend-fill ${w.count?'has-data':''}" style="height:${Math.round(w.count/top*100)}%"></div></div><small>${i===7?'Tuần này':niceDate(w.start).slice(0,5)}</small></div>`).join('')}</div>`;
}
function home(){
 const plan=getPlan(monday(today())), stats=weeklyStats(state.logs,today());
 const upcoming=plan.days.filter(d=>d.kind==='planned'),done=plan.days.filter(d=>d.kind==='done');
 const current=weeklyTrainingData(plan),ratio=Math.min(100,Math.round((done.length/3)*100));
 const displayName=state.settings.nickname?esc(state.settings.nickname):'Khai Trí';
 const recent=upcoming[0];
 return `
<section class="hero premium-hero">
  <div class="hero-content">
    <div class="hero-kicker"><span class="hero-kicker-pulse"></span> TRAIN WITH INTENT · YOUR DAILY MOVE</div>
    <h1>Chào ${displayName}.<br><em>Hôm nay bạn mạnh hơn hôm qua.</em></h1>
    <p>Không cần hoàn hảo. Chỉ cần bắt đầu — GymOS sẽ giúp bạn tập đúng, ghi nhận tiến bộ và tự sắp xếp lịch phù hợp.</p>
    <div class="buttonrow hero-actions">
      ${recent?btn('▶ Bắt đầu · '+sessionName(recent.type),'open-workout','btn primary',`data-date="${recent.date}" data-type="${recent.type}"`):btn('Xem lịch tập tuần','go-week','btn primary')}
      ${btn('Xem kế hoạch 7 ngày','go-week','btn outline')}
    </div>
    <div class="hero-footnotes"><span>✓ Lịch tập thông minh</span><span>✓ Bài tập & cardio</span><span>✓ Nhật ký riêng tư</span></div>
  </div>
  <div class="hero-progress" aria-label="${done.length} trên 3 buổi tuần này"><strong>${done.length}<small>/3</small></strong><span>BUỔI TUẦN NÀY</span><div class="hero-mini-track"><span style="width:${ratio}%"></span></div></div>
</section>
<div class="dashboard-heading"><div><span class="eyebrow">YOUR PERFORMANCE</span><h2>Tập đều. Tiến bộ thật.</h2></div><span class="dashboard-week-label">${niceDate(plan.start)} – ${niceDate(plan.end)}</span></div>
<section class="metric-grid premium-metrics" aria-label="Chỉ số luyện tập">
 <div class="metric"><div class="metric-top">BUỔI TẬP TUẦN NÀY <span class="metric-symbol">◉</span></div><div class="metric-value">${done.length}<span class="metric-unit"> / 3</span></div><div class="metric-foot">${plan.doneStrength}/2 buổi sức mạnh được ghi nhận</div></div>
 <div class="metric"><div class="metric-top">PHÚT TẬP ĐÃ GHI <span class="metric-symbol">◷</span></div><div class="metric-value">${current.allMinutes}<span class="metric-unit"> phút</span></div><div class="metric-foot">Từ các buổi hoàn thành trong tuần</div></div>
 <div class="metric"><div class="metric-top">THỜI GIAN CARDIO <span class="metric-symbol">♡</span></div><div class="metric-value">${current.cardioMinutes}<span class="metric-unit"> phút</span></div><div class="metric-foot">Đã ghi trong tuần này</div></div>
 <div class="metric"><div class="metric-top">SET HOÀN THÀNH <span class="metric-symbol">▥</span></div><div class="metric-value">${current.sets}</div><div class="metric-foot">Các set bạn đã đánh dấu xong</div></div>
</section>
<div class="dashboard-two-col">
 <section class="panel dashboard-week-card"><div class="panel-heading"><div><div class="eyebrow">THIS WEEK</div><h2>Kế hoạch 7 ngày</h2></div><button class="subtle-link" data-action="go-week">Chi tiết ↗</button></div>${weekStrip(plan)}<div class="week-progress-info"><span>${done.length} / 3 buổi hoàn thành</span><span>${ratio}% mục tiêu tuần</span></div><div class="mini-progress"><div style="width:${ratio}%"></div></div></section>
 <section class="panel dashboard-trend-card"><div class="panel-heading"><div><div class="eyebrow">CONSISTENCY</div><h2>Nhịp tập 8 tuần</h2></div><span class="chip green">${stats.streak} tuần duy trì</span></div><p class="muted-sm">Mỗi cột là số buổi đã hoàn thành trong tuần. Không ước lượng hay tạo dữ liệu mẫu.</p>${attendanceTrend(plan.start)}<p class="trend-caption">${stats.total?'Duy trì đều đặn quan trọng hơn tập quá sức trong một ngày.':'Bạn chưa có nhật ký. Hãy hoàn thành buổi đầu tiên để biểu đồ bắt đầu xuất hiện.'}</p></section>
</div>
<div class="dashboard-heading feature-heading"><div><span class="eyebrow">CHOOSE YOUR NEXT MOVE</span><h2>Hôm nay bạn muốn tập gì?</h2></div></div>
<div class="program-grid">
 <button type="button" data-action="go-week" class="program-card strength-program"><span class="program-mark">01 / STRENGTH</span><div class="program-icon">↗</div><h3>Full Body &<br>tập nhóm cơ</h3><p>Lịch A/B hoặc chuyên ngực, vai, lưng, chân.</p><span class="program-cta">Mở lịch tập <b>→</b></span></button>
 <button type="button" data-action="go-cardio" class="program-card cardio-program"><span class="program-mark">02 / ENDURANCE</span><div class="program-icon">♡</div><h3>Cardio &<br>sức bền</h3><p>Treadmill, máy tập, bodyweight và circuit.</p><span class="program-cta">Khám phá cardio <b>→</b></span></button>
 <button type="button" data-action="go-library" class="program-card library-program"><span class="program-mark">03 / EXERCISES</span><div class="program-icon">▤</div><h3>Thư viện<br>bài tập</h3><p>Hướng dẫn từng bước, nhịp thở và bài thay thế.</p><span class="program-cta">Xem bài tập <b>→</b></span></button>
</div>
<div class="dashboard-two-col lower-dashboard">
 <section class="panel"><div class="panel-heading"><div><div class="eyebrow">UPCOMING</div><h2>Buổi sắp tới</h2></div><span class="chip">${upcoming.length} buổi chờ</span></div><div class="action-list">${upcoming.length?upcoming.slice(0,2).map(sessionCard).join(''):'<div class="empty"><h3>Bạn đã xong lịch gợi ý</h3><p>Tuần kế tiếp sẽ tự tạo lịch mới. Bạn vẫn có thể chọn cardio nhẹ hoặc ngày phục hồi.</p></div>'}</div></section>
 <section class="panel"><div class="panel-heading"><div><div class="eyebrow">GET STARTED</div><h2>Đi bộ máy: nhẹ mà hiệu quả</h2></div></div>${walkInfo(false)}<div class="buttonrow" style="margin-top:13px">${btn('Xem các bài cardio','go-cardio','btn small outline')}</div></section>
</div>
${healthNote()}`;
}
function week(){const plan=getPlan(weekStart);return `${title('KẾ HOẠCH THÍCH NGHI','Lịch tập theo tuần','Dùng Full Body, chuyên nhóm cơ hoặc 6 loại cardio. Tập cardio khác đi bộ máy vẫn được tính vào mục tiêu tuần.',`<div class="week-nav">${btn('‹','week-prev','square-btn')}<span class="chip green">${niceDate(plan.start)} – ${niceDate(plan.end)}</span>${btn('›','week-next','square-btn')} ${btn('Tuần này','week-current','btn small')}</div>`)}<div class="week-detail"><div class="stack"><div class="panel"><div class="panel-heading"><h2>Tổng quan 7 ngày</h2><span class="chip">${plan.completed} / 3 buổi</span></div>${weekStrip(plan)}</div><div class="panel"><div class="panel-heading"><h2>Từng ngày trong tuần</h2></div><div class="timeline">${plan.days.map(d=>timelineDay(d)).join('')}</div></div></div><div class="stack"><div class="panel"><h3>Lịch thích nghi hoạt động như thế nào?</h3><div class="week-guide"><p>① Gợi ý 2 buổi sức mạnh/tuần. Buổi chuyên nhóm cơ được tính là một buổi tạ, thay vì tự động cộng thêm A/B.</p></div><div class="week-guide"><p>② App xếp các buổi tạ gợi ý cách nhau ít nhất 48 giờ; nếu bạn tự chọn ngày sát nhau, hãy xem cảnh báo phục hồi.</p></div><div class="week-guide"><p>③ Nếu bỏ buổi, app dời những buổi còn lại. Nếu hết ngày, tiếp tục xoay A/B tuần sau, không ép tập bù.</p></div><div class="week-guide"><p>④ Buổi cardio mặc định là đi bộ máy, nhưng bạn có thể đổi sang xe đạp, elliptical, rowing hoặc circuit bodyweight/dụng cụ. Lịch không ép tập bù cardio.</p></div><div class="divider"></div>${plan.unplanned.length?`<div class="shift-explain"><strong>Không thể xếp đủ trong tuần:</strong> ${plan.unplanned.map(t=>sessionName(t)).join(', ')}. Đây là chủ ý để không dồn buổi.</div>`:'<div class="shift-explain"><strong>Đã phân bổ đủ các buổi có thể tập.</strong> Mỗi khi bạn đánh dấu hoàn thành hoặc bỏ buổi, lịch cập nhật.</div>'}</div><div class="panel">${walkInfo(false)}<div class="buttonrow" style="margin-top:12px">${btn('Tùy chọn cardio ↗','go-cardio','btn small outline')}</div></div></div></div>`;}
function timelineDay(d){const s=SESSIONS[d.type], badge=d.kind==='done'?'<span class="chip green">✓ Hoàn thành</span>':d.kind==='skipped'?'<span class="chip warning">Đã bỏ</span>':d.kind==='past'?'<span class="chip dim">Đã qua</span>':s?sessionPill(d.type):'<span class="chip dim">Phục hồi</span>';const dayinfo=d.kind==='done'?`Ghi nhận ${sessionName(d.type)}${d.log?.minutes?' · '+esc(d.log.minutes)+' phút':''}`:d.kind==='skipped'?'Bạn chủ động bỏ ngày này; lịch đã tự cập nhật':s?`${s.description} · ${s.time}`:'Nghỉ hoặc đi bộ rất nhẹ tùy sức';const can=d.date<=today(), future=d.date>today();let actions='';if(d.kind==='done')actions=btn('Xem/sửa','open-workout','btn small outline',`data-date="${d.date}" data-type="${d.type}"`);else if(d.kind==='skipped')actions=btn('Hoàn tác','undo-skip','btn small',`data-date="${d.date}"`);else if(future||d.date===today())actions=(s?btn('Bắt đầu','open-workout','btn small primary',`data-date="${d.date}" data-type="${d.type}"`):btn('Tập thêm','day','btn small outline',`data-date="${d.date}"`))+' '+btn('Bỏ','skip-day','btn small danger',`data-date="${d.date}"`);else actions=btn('Ghi bù','day','btn small outline',`data-date="${d.date}"`);return `<div class="timeline-day ${d.date===today()?'current':''}"><div class="timeline-date"><strong>${parse(d.date).getDate()}</strong><span>${niceDay(d.date)}</span></div><div class="timeline-content"><h3>${badge}</h3><p>${esc(dayinfo)}</p></div><div class="timeline-actions">${actions}</div></div>`;}
function cardio(){
 const total=cardioExercises(),arr=total.filter(([,x])=>cardioFilter==='all'||x.cardioCategory===cardioFilter);
 const modes=Object.entries(SESSIONS).filter(([id])=>isCardio(id));
 const stats=weeklyStats(state.logs,today()),start=monday(today()),end=move(start,6);
 const weeklyMinutes=Object.entries(state.logs).filter(([date,log])=>date>=start&&date<=end&&log?.completed&&isCardio(log.type)).reduce((n,[,log])=>n+(Number(log.minutes)||0),0);
 return `${title('CARDIO · ENDURANCE','Tim mạch khỏe hơn, từng buổi một','Không cần nhảy hay chạy nước rút. Tập bằng máy cardio, bodyweight hoặc dụng cụ có sẵn tại phòng gym.')}
 <div class="cardio-hero"><div><div class="eyebrow aqua">SỨC BỀN · MỨC LÀM QUEN</div><h2 style="margin:9px 0">${weeklyMinutes} phút cardio tuần này</h2><p>Bắt đầu 1–2 buổi × 15–25 phút, tăng dần khi cơ thể thích nghi. Mục tiêu dài hạn hướng tới 150 phút/tuần cường độ vừa, kết hợp ít nhất 2 buổi tập cơ; không cần đạt ngay.</p><div class="buttonrow" style="margin-top:16px">${btn('Chọn buổi cardio hôm nay','day','btn primary',`data-date="${today()}"`)}${btn('Xem thư viện cardio','go-cardio-library','btn outline')}</div></div><div class="cardio-hero-stats"><strong>${weeklyMinutes}<small>phút / tuần</small></strong><small>RPE nên ở mức 3–4/10<br>vẫn nói chuyện được</small></div></div>
 <div class="cardio-mode-grid">${CARDIO_CATEGORIES.map(c=>`<button class="cardio-mode ${cardioFilter===c.id?'selected':''}" data-action="cardio-filter" data-filter="${c.id}"><span class="cardio-mode-icon">${c.icon}</span><strong>${esc(c.name)}</strong><span>${esc(c.description)}</span><small>${total.filter(([,x])=>x.cardioCategory===c.id).length} bài</small></button>`).join('')}</div>
 <section class="panel" style="margin-bottom:20px"><div class="panel-heading"><h2>6 buổi mẫu có thể đổi cho nhau</h2><span class="chip aqua">Chọn để tập hôm nay</span></div><p class="muted-sm" style="margin-bottom:16px">Hai buổi Full Body vẫn là phần trọng tâm. Một buổi cardio bất kỳ đã hoàn thành sẽ thay thế buổi đi bộ máy trong lịch đề xuất.</p><div class="cardio-session-grid">${modes.map(([id,s])=>`<article class="cardio-plan-card"><span class="cardio-plan-icon">${s.icon}</span><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p><div class="exercise-specs"><span class="chip">${esc(s.time)}</span><span class="chip ${s.cardioMode==='circuit'?'purple':'aqua'}">${s.cardioMode==='circuit'?'Circuit':'Liên tục'}</span></div>${btn('Chọn buổi này','start-cardio','btn small primary',`data-type="${id}"`)}</article>`).join('')}</div></section>
 <section class="panel"><div class="panel-heading"><h2>Thư viện cardio: ${arr.length} / ${total.length} bài</h2><span class="chip aqua">Máy · Bodyweight · Dụng cụ</span></div><div class="buttonrow" style="margin-bottom:18px">${[['all','Tất cả'],...CARDIO_CATEGORIES.map(x=>[x.id,x.name])].map(([id,name])=>btn(name,'cardio-filter','btn small '+(id===cardioFilter?'primary':'outline'),`data-filter="${id}"`)).join('')}</div><div class="exercise-grid">${arr.map(([id,x])=>`<article class="exercise-list-card"><div class="exercise-tag">${esc(x.equipment)} · ${esc(x.difficulty)}</div><div class="exercise-head"><span class="exercise-emoji">${x.icon}</span><div><h3>${esc(x.vi)}</h3><p class="vietnamese">${esc(x.name)}</p></div></div><div class="exercise-specs"><span class="chip aqua">${esc(x.reps)}</span><span class="chip ${moderateCardio(x)?'dim':'warning'}">${esc(x.intensity||'Vừa')}</span></div><p class="muted-sm">${esc(x.avoid)}</p><div class="buttonrow">${btn('Cách tập ↗','exercise','btn small primary',`data-exercise="${id}"`)}<a class="btn small outline" target="_blank" rel="noopener noreferrer" href="${esc(x.video)}">▶ Tìm video ↗</a></div></article>`).join('')}</div></section>
 ${healthNote()}`;
}
function library(){
 const counts=Object.fromEntries(MUSCLE_GROUPS.map(g=>[g.id,Object.values(EXERCISES).filter(x=>getGroup(x)===g.id).length]));
 const arr=Object.entries(EXERCISES).filter(([id,x])=>{const term=(x.vi+' '+x.name+' '+x.group+' '+x.equipment+' '+(x.primaryMuscle||'')).toLocaleLowerCase('vi-VN');return (exerciseFilter==='all'||(exerciseFilter==='strength'?x.group!=='Tim mạch':exerciseFilter==='cardio'?x.group==='Tim mạch':exerciseFilter==='machine'||exerciseFilter==='bodyweight'||exerciseFilter==='equipment'?x.cardioCategory===exerciseFilter:exerciseFilter==='easy'?x.difficulty==='Dễ'||x.difficulty==='Rất dễ':getGroup(x)===exerciseFilter))&&term.includes(exerciseQuery.toLocaleLowerCase('vi-VN'));});
 arr.sort((a,b)=>(a[1].difficulty==='Dễ'?0:1)-(b[1].difficulty==='Dễ'?0:1));
 return `${title('THƯ VIỆN HƯỚNG DẪN',`${Object.keys(EXERCISES).length} bài tập · có hình minh họa nhanh`,'Mỗi bài có ảnh minh họa để hình dung form trước khi mở video. Dùng bộ lọc theo nhóm cơ, cardio hoặc độ khó.')}
 <div class="panel muscle-panel"><div class="panel-heading"><h2>Chọn nhóm cơ để khám phá</h2><span class="chip">${arr.length} bài đang hiển thị</span></div><div class="muscle-grid">${MUSCLE_GROUPS.map(g=>`<button type="button" class="muscle-card ${exerciseFilter===g.id?'selected':''}" data-action="filter" data-filter="${g.id}"><span class="muscle-icon">${g.icon}</span><b>${esc(g.name)}</b><small>${counts[g.id]} bài</small><span class="muscle-desc">${esc(g.description)}</span></button>`).join('')}</div><p class="muted-sm" style="margin-top:13px">Buổi chuyên nhóm cơ: vào <b>Lịch tuần</b>, chạm ngày muốn tập và chọn nhóm cơ. Có thể thêm/bớt bài trước khi tick set.</p></div>
 <div class="filter-row"><input class="search-input" id="exerciseSearch" type="search" placeholder="Tìm bài, cơ chính, máy hoặc tạ..." value="${esc(exerciseQuery)}" aria-label="Tìm bài tập"><div class="tab-filters">${[['all','Tất cả'],['strength','Tập cơ'],['cardio','Cardio'],['machine','Máy cardio'],['bodyweight','Bodyweight'],['equipment','Dụng cụ'],['easy','Dễ học']].map(([v,t])=>`<button class="tab-filter ${exerciseFilter===v?'active':''}" data-action="filter" data-filter="${v}">${t}</button>`).join('')}</div></div><p class="muted-sm" style="margin:7px 0 16px">${arr.length} bài phù hợp bộ lọc · Ảnh dùng để hình dung nhanh form, còn video sẽ giúp xem đầy đủ biên độ và nhịp tập.</p>
 <div class="exercise-grid">${arr.map(([id,x])=>`<article class="exercise-list-card">${previewImg(x,'exercise-cover',x.vi)}<div class="exercise-card-body"><div class="exercise-tag-row"><div class="exercise-tag">${x.group==='Tim mạch'?'Tim mạch':esc(muscleName(getGroup(x)))}</div><div class="exercise-tag subtle">${esc(movementLabel(x))}</div></div><div class="exercise-head noicon"><div><h3>${esc(x.name)}</h3><p class="vietnamese">${esc(x.vi)}</p></div></div><p class="muted-sm">🎯 Cơ chính: ${esc(x.primaryMuscle||x.group)}</p><div class="exercise-specs"><span class="chip">${x.group==='Tim mạch'?x.reps:x.sets+' set × '+x.reps}</span><span class="chip dim">${esc(x.difficulty)}</span></div><p class="muted-sm">🌬 ${esc(x.breath)}</p><div class="buttonrow">${btn('Cách tập & thở ↗','exercise','btn small primary',`data-exercise="${id}"`)}<a class="btn small outline" href="${esc(x.video)}" target="_blank" rel="noopener noreferrer">▶ Video</a></div></div></article>`).join('')}</div>`;
}
function videoSearch(ex){return `https://www.youtube.com/results?search_query=${encodeURIComponent(ex.name+" proper form exercise tutorial")}`;}
function exercisePage(){const id=selectedExercise,x=EXERCISES[id];if(!x)return library();return `<div class="buttonrow" style="margin-bottom:16px">${btn('← Thư viện','go-library','btn small outline')}</div><div class="detail-hero detail-hero-visual"><div class="detail-top"><div><div class="eyebrow">BÀI TẬP · ${esc(x.group)}</div><h1>${esc(x.vi)}</h1><p class="muted">${esc(x.name)} · ${esc(x.equipment)}</p><div class="buttonrow" style="margin-top:20px"><span class="chip green">${x.group==='Tim mạch'?x.reps:x.sets+' set × '+x.reps}</span><span class="chip">Nghỉ ${x.rest || '—'} giây</span><span class="chip dim">${esc(movementLabel(x))}</span></div></div>${previewImg(x,'exercise-visual',x.vi)}</div><p class="muted-sm" style="margin-top:14px">Hình minh họa nhanh để hình dung tư thế trước khi xem video. Khi muốn kiểm tra biên độ đầy đủ, hãy mở video ở nút bên dưới.</p><div class="buttonrow" style="margin-top:16px"><a class="btn primary" href="${esc(x.video)}" target="_blank" rel="noopener noreferrer">▶ Video / minh họa ↗</a><a class="btn outline" target="_blank" rel="noopener noreferrer" href="${videoSearch(x)}">Tìm thêm video trên YouTube ↗</a></div></div><div class="exercise-detail-layout"><div class="stack"><section class="panel"><h2>Cách thực hiện từng bước</h2><div class="muscle-target"><div><b>🎯 ${x.group==='Tim mạch'?'Mục tiêu':'Cơ chính'}</b><span>${esc(x.primaryMuscle||x.group)}</span></div><div><b>↗ Cơ phụ</b><span>${esc(x.secondaryMuscles||'Xem nhóm cơ mô tả ở trên')}</span></div><div><b>🏷 Độ khó</b><span>${esc(x.difficulty)}</span></div></div><ol class="instruction-list">${x.steps.map(z=>`<li>${esc(z)}</li>`).join('')}</ol></section><section class="panel"><h3>Bài tập thay thế</h3><p class="muted-sm" style="margin:8px 0 14px">Dùng nếu máy đang bận hoặc bài tập gây khó chịu; nếu đau, ngưng và tìm nguyên nhân.</p><div class="action-list">${x.alternatives.filter(k=>k!=='bike').map(k=>EXERCISES[k]?`<div class="session-card"><div class="exercise-emoji">${EXERCISES[k].icon}</div><div class="session-info"><strong>${esc(EXERCISES[k].vi)}</strong><p>${esc(EXERCISES[k].equipment)}</p></div>${btn('Xem','exercise','btn small',`data-exercise="${k}"`)}</div>`:'').join('')}</div></section></div><div class="stack"><div class="panel"><div class="hint-row"><div class="hint breath-hint"><b>🌬 Cách thở đúng</b>${breathingMarkup(x)}</div><div class="hint warn"><b>⚠ Lỗi cần tránh</b>${esc(x.avoid)}</div></div></div><div class="panel"><h3>Nhắc nhanh cho người mới</h3><p class="muted-sm" style="margin-top:9px">${x.group==='Tim mạch'?'Khởi động 5 phút, vận động ở mức vẫn trò chuyện được rồi thả lỏng 5 phút. Bắt đầu 10–20 phút, nâng thời lượng trước cường độ. Nếu bài ghi Nâng cao, chỉ cân nhắc sau khi đã quen và được bác sĩ đồng ý khi cần.':'Tập thử 1 set thật nhẹ để làm quen máy, sau đó 2 set chính. Bạn nên còn sức thực hiện 2–3 rep nữa. Nếu chưa biết chỉnh máy, nhờ nhân viên hướng dẫn trước. Khi rep nặng dần, ưu tiên kỹ thuật và nhịp thở ổn định hơn là thêm tạ.'}</p></div></div></div>`;}
function draftFor(date,type){
 const s=SESSIONS[type];
 const existing=state.drafts[date];
 if(existing?.type===type){if(!Array.isArray(existing.exerciseIds))existing.exerciseIds=[...(s?.exerciseIds||[])];return normalizeCardioDraft(existing,type);}
 const saved=state.logs[date];
 if(saved?.type===type){
   const draft={...saved,exercises:saved.exercises||{},exerciseIds:Array.isArray(saved.exerciseIds)?[...saved.exerciseIds]:[...(s?.exerciseIds||[])],notes:saved.notes||''};
   state.drafts[date]=draft;return normalizeCardioDraft(draft,type);
 }
 const defaults={C:25,D:25,E:25,F:18,G:18,H:20};
 const draft={type,exercises:{},exerciseIds:[...(s?.exerciseIds||[])],minutes:defaults[type]||45,speed:4.0,incline:0,effort:4,notes:''};
 state.drafts[date]=draft;normalizeCardioDraft(draft,type);save();return draft;
}
function normalizeCardioDraft(draft,type){
 if(!isCardio(type))return draft;
 if(!Array.isArray(draft.cardioChecked))draft.cardioChecked=[];
 if(!Number.isFinite(Number(draft.rounds)))draft.rounds=2;
 if(!Number.isFinite(Number(draft.workSec)))draft.workSec=type==='H'?45:40;
 if(!Number.isFinite(Number(draft.restSec)))draft.restSec=type==='H'?30:20;
 if(draft.resistance===undefined)draft.resistance='';
 if(draft.strokes===undefined)draft.strokes='';
 return draft;
}
function lastExercise(id,excludeDate){const logs=Object.entries(state.logs).filter(([d,log])=>log?.completed && d!==excludeDate && log.exercises).sort((a,b)=>b[0].localeCompare(a[0]));for(const [date,log] of logs)for(const [k,v] of Object.entries(log.exercises)){if((v?.replacement||k)===id && (v.sets||[]).some(s=>s.done))return {date,sets:v.sets.filter(s=>s.done)};}return null;}
function defaultSets(base,date){const ex=EXERCISES[base],last=lastExercise(base,date),prevWeight=last?.sets?.[0]?.weight||'';return Array.from({length:ex.sets},()=>({reps:'',weight:prevWeight,done:false}));}
function getExerciseDraft(draft,base,date){if(!draft.exercises[base])draft.exercises[base]={replacement:base,sets:defaultSets(base,date)};const val=draft.exercises[base];if(!Array.isArray(val.sets))val.sets=defaultSets(base,date);return val;}
function exerciseWorkout(id,draft,date){const item=getExerciseDraft(draft,id,date),current=EXERCISES[item.replacement] || EXERCISES[id],allOptions=[id,...EXERCISES[id].alternatives].filter(k=>k!=='bike'&&EXERCISES[k]);const sets=item.sets||[];const last=lastExercise(item.replacement,date);return `<article class="workout-exercise"><div class="exercise-toggle">${previewImg(current,'workout-thumb',current.vi)}<div class="exercise-title"><h3>${esc(current.vi)}</h3><p>${esc(current.name)} · ${esc(current.equipment)}</p><div class="exercise-mini-meta"><span class="chip">${current.reps}</span><span class="chip dim">${esc(current.difficulty)}</span></div></div></div><div class="exercise-body"><p class="muted-sm"><b>🎯 ${esc(current.primaryMuscle||current.group)}</b> · Cơ phụ: ${esc(current.secondaryMuscles||'Tùy biến thể')}</p><p class="muted-sm">${esc(current.steps[0])}</p><div class="hint-row"><div class="hint breath-hint"><b>🌬 Thở đúng</b>${breathingMarkup(current)}</div><div class="hint warn"><b>⚠ Đừng làm</b>${esc(current.avoid)}</div></div><div class="buttonrow"><a class="btn small" href="${esc(current.video)}" target="_blank" rel="noopener noreferrer">▶ Video / minh họa ↗</a><a class="btn small outline" href="${videoSearch(current)}" target="_blank" rel="noopener noreferrer">YouTube ↗</a>${btn('Cách tập chi tiết','exercise','btn small outline',`data-exercise="${item.replacement}"`)}${btn('Bỏ bài này','remove-exercise','btn small danger',`data-exercise="${id}"`)}</div><div class="swap-row"><label class="muted-sm" for="swap-${id}">Máy bận / không làm được?</label><select id="swap-${id}" data-swap="${id}" aria-label="Bài thay thế cho ${esc(current.vi)}">${allOptions.map(k=>`<option value="${k}" ${k===item.replacement?'selected':''}>${esc(EXERCISES[k].vi)}</option>`).join('')}</select></div>${last?`<p class="muted-sm">Lần trước (${niceDate(last.date)}): ${last.sets.map(s=>`${esc(s.weight||'—')} kg × ${esc(s.reps||'—')}`).join(' · ')}</p>`:''}<div class="set-grid head"><span>SET</span><span>REP</span><span>TẠ (KG)</span><span>✓</span></div>${sets.map((s,i)=>`<div class="set-grid ${s.done?'checked':''}"><span class="set-num">${String(i+1).padStart(2,'0')}</span><input class="field" data-set="${id}" data-index="${i}" data-field="reps" type="number" min="0" max="60" inputmode="numeric" value="${esc(s.reps)}" placeholder="${current.reps.match(/\d+/)?.[0]||'10'}" aria-label="Số lần set ${i+1}"><input class="field" data-set="${id}" data-index="${i}" data-field="weight" type="number" min="0" max="500" step="0.5" inputmode="decimal" value="${esc(s.weight)}" placeholder="0" aria-label="Tạ kg set ${i+1}"><label class="donecheck"><input type="checkbox" data-set="${id}" data-index="${i}" data-field="done" ${s.done?'checked':''} aria-label="Hoàn thành set ${i+1}"></label></div>`).join('')}<p class="muted-sm">Nghỉ ${current.rest} giây giữa set · tạ nhẹ, còn sức 2–3 rep · ưu tiên thở đều và không nín thở.</p>${btn(`Đặt nghỉ ${current.rest} giây`,'set-timer','btn small soft',`data-seconds="${current.rest}"`)}</div></article>`;}
function strengthWorkoutEditor(s,draft,date){
 const chosen=draft.exerciseIds||s.exerciseIds;
 const available=Object.entries(EXERCISES).filter(([id,x])=>x.group!=='Tim mạch'&&!chosen.includes(id));
 return `<div class="callout green"><b>Khởi động trước khi nâng tạ</b>Đi bộ máy 5 phút ở 3–3,5 km/h, dốc 0%. Sau đó xoay khớp nhẹ và thử 1 set rất ít tạ.</div><div class="exercise-stack">${chosen.map(id=>EXERCISES[id]?exerciseWorkout(id,draft,date):'').join('')}</div><div class="custom-workout"><h3>＋ Tùy biến buổi tập</h3><p class="muted-sm">Thêm bài từ thư viện (tối đa 8 bài). Người mới nên giữ 4–6 bài/buổi.</p><div class="custom-row"><select id="addExerciseSelect" class="field" aria-label="Chọn bài để thêm"><option value="">Chọn bài để thêm vào buổi…</option>${available.sort((a,b)=>(getGroup(a[1])===s.groupId?-1:1)-(getGroup(b[1])===s.groupId?-1:1)).map(([id,x])=>`<option value="${id}">${esc(muscleName(getGroup(x)))} · ${esc(x.vi)} · ${esc(x.equipment)}</option>`).join('')}</select>${btn('Thêm bài','add-exercise','btn primary small')}</div></div>`;
}
function cardioWorkoutEditor(s,draft){
 const chosen=draft.exerciseIds.filter(id=>EXERCISES[id]?.group==='Tim mạch');
 const circuit=s.cardioMode==='circuit';
 const available=cardioExercises().filter(([id])=>!chosen.includes(id));
 return `<div class="cardio-safety-bar"><b>♡ Mức khởi đầu: RPE 3–4/10</b><span>Vẫn nói được câu đầy đủ. Khởi động 5 phút, thả lỏng 5 phút; không cần chạy hay HIIT.</span></div>
 ${workoutType==='C'?`${walkInfo(false)}<div class="divider"></div>`:''}
 <div class="cardio-routine-caption"><strong>${circuit?'🔁 Circuit ít tác động khớp':'🚶 Cardio nhịp đều'}</strong><p>${circuit?`Mặc định ${esc(draft.rounds)} vòng; ${esc(draft.workSec)} giây vận động / ${esc(draft.restSec)} giây nghỉ. Nên nghỉ thêm nếu khó nói chuyện.`:'Đi liên tục ở mức vừa sức. Tốc độ, lực cản và mức dốc chỉ là gợi ý, không phải mục tiêu bắt buộc.'}</p></div>
 <div class="cardio-exercise-stack">${chosen.map((id)=>{const x=EXERCISES[id],enabled=draft.cardioChecked.includes(id);return `<article class="cardio-move"><div class="cardio-move-title">${previewImg(x,'workout-thumb cardio-thumb',x.vi)}<div><h3>${esc(x.vi)}</h3><p>${esc(x.name)} · ${esc(x.equipment)}</p></div><span class="chip ${moderateCardio(x)?'aqua':'warning'}">${esc(x.difficulty)}</span></div><div class="cardio-move-body"><p class="muted-sm">${esc(x.steps[0])}</p><ol class="instruction-list">${x.steps.slice(1).map(step=>`<li>${esc(step)}</li>`).join('')}</ol><div class="hint-row"><div class="hint breath-hint"><b>🌬 Thở</b>${breathingMarkup(x)}</div><div class="hint warn"><b>⚠ Chú ý</b>${esc(x.avoid)}</div></div><div class="buttonrow"><a class="btn small outline" target="_blank" rel="noopener noreferrer" href="${esc(x.video)}">▶ Tìm video ↗</a>${btn('Chi tiết','exercise','btn small',`data-exercise="${id}"`)}${btn('Bỏ bài','remove-cardio','btn small danger',`data-exercise="${id}"`)}</div><label class="cardio-check"><input type="checkbox" data-cardio-check="${id}" ${enabled?'checked':''}><span>Đã thực hiện bài này</span></label></div></article>`;}).join('')}</div>
 <div class="custom-workout"><h3>＋ Thay / thêm bài cardio</h3><p class="muted-sm">Chọn bất kỳ bài trong 3 nhóm: máy, bodyweight và dụng cụ. Giữ 1 bài cardio liên tục hoặc 3–4 bài circuit. Các bài nâng cao có nhãn cảnh báo và không được tự thêm vào gợi ý ban đầu.</p><div class="custom-row"><select id="addCardioSelect" class="field" aria-label="Chọn bài cardio"><option value="">Chọn bài cardio...</option>${available.sort((a,b)=>(moderateCardio(a[1])?-1:1)-(moderateCardio(b[1])?-1:1)).map(([id,x])=>`<option value="${id}">${esc(x.vi)} · ${esc(x.equipment)}${moderateCardio(x)?'':' · NÂNG CAO'}</option>`).join('')}</select>${btn('Thêm cardio','add-cardio','btn primary small')}</div></div>
 <div class="divider"></div>
 <div class="form-grid cardio-form"><label class="form-label">Thời lượng thực tế (phút)<input id="cardioMinutes" class="field" type="number" min="1" max="240" value="${esc(draft.minutes)}" inputmode="numeric"></label><label class="form-label">RPE thực tế (0–10)<input id="effort" class="field" type="number" min="0" max="10" value="${esc(draft.effort)}"></label>
 ${circuit?`<label class="form-label">Số vòng<input id="cardioRounds" class="field" type="number" min="1" max="8" value="${esc(draft.rounds)}"></label><label class="form-label">Vận động (giây)<input id="cardioWork" class="field" type="number" min="15" max="180" step="5" value="${esc(draft.workSec)}"></label><label class="form-label">Nghỉ mỗi bài (giây)<input id="cardioRest" class="field" type="number" min="10" max="180" step="5" value="${esc(draft.restSec)}"></label>`:''}
 ${chosen.some(id=>['treadmill','mTreadIncline','mCurved'].includes(id))?`<label class="form-label">Tốc độ máy (km/h)<input id="cardioSpeed" type="number" class="field" min="0" max="12" step="0.1" value="${esc(draft.speed)}"></label><label class="form-label">Độ dốc máy (%)<input id="cardioIncline" type="number" class="field" min="0" max="15" step="0.5" value="${esc(draft.incline)}"></label>`:''}
 ${chosen.some(id=>['bike','elliptical','mRecumbent','mAirBike','mStair','mArc','mSki','mRow'].includes(id))?`<label class="form-label">Kháng lực theo máy (tùy chọn)<input id="cardioResistance" class="field" inputmode="numeric" type="number" min="0" max="100" step="1" placeholder="Ví dụ: 3" value="${esc(draft.resistance)}"></label>`:''}
 ${chosen.some(id=>id==='mRow')?`<label class="form-label">Nhịp chèo (stroke/phút, tùy chọn)<input id="cardioStrokes" class="field" type="number" min="0" max="80" value="${esc(draft.strokes)}"></label>`:''}
 </div><p class="muted-sm" style="margin-top:12px">Tập theo cảm giác, không ép đạt một nhịp tim cố định. Nếu đau ngực, choáng/ngất, khó thở khác thường hoặc đánh trống ngực kéo dài: dừng tập và tìm hỗ trợ y tế.</p>`;
}
function workout(){
 const type=workoutType,date=workoutDate,s=SESSIONS[type];if(!s)return week();
 const draft=draftFor(date,type),completed=state.logs[date]?.completed,cardio=isCardio(type);
 const doneSets=Object.values(draft.exercises).reduce((sum,x)=>sum+(x.sets||[]).filter(y=>y.done).length,0);
 return `<div class="buttonrow" style="margin-bottom:16px">${btn('← Lịch tập','go-week','btn small outline')}${cardio?btn('♡ Cardio','go-cardio','btn small outline'):''}${completed?'<span class="chip green">✓ Buổi đã hoàn thành · chỉnh sửa được</span>':''}</div><div class="session-header"><div class="eyebrow">${dateTitle(date)} · ${cardio?'CARDIO & SỨC BỀN':'STRENGTH'}</div><h1>${esc(s.name)} <span style="color:var(--lime)">/ ${esc(s.title)}</span></h1><p class="muted" style="margin:10px 0 23px">${esc(s.description)} · ${esc(s.time)}</p></div>
 <div class="workout-layout"><div class="stack"><div class="panel"><div class="panel-heading"><h2>${cardio?'Bài cardio hôm nay':'Bài tập hôm nay'}</h2><span class="chip">${cardio?draft.exerciseIds.length+' bài cardio':draft.exerciseIds.length+' bài tạ'}</span></div>${cardio?cardioWorkoutEditor(s,draft):strengthWorkoutEditor(s,draft,date)}</div>
 <div class="panel"><div class="panel-heading"><h3>Hoàn thành buổi tập</h3><span class="chip green" id="checkedSets">${cardio?draft.cardioChecked.length+' bài đã tick':doneSets+' set đã tick'}</span></div>${cardio?'':`<div class="form-grid"><label class="form-label">Thời lượng thực tế (phút)<input id="sessionMinutes" type="number" class="field" min="0" max="240" value="${esc(draft.minutes)}"></label><label class="form-label">Mức gắng sức (0–10)<input id="effort" type="number" class="field" min="0" max="10" value="${esc(draft.effort)}"></label></div>`}<label class="form-label" style="margin-top:14px">Ghi chú (cảm giác khi tập, máy bận, đau ở đâu…)<textarea id="sessionNotes" class="field" rows="3" placeholder="Ví dụ: đạp xe 20 phút, RPE 4, vẫn nói chuyện thoải mái...">${esc(draft.notes)}</textarea></label><div class="finishbar"><div class="buttonrow">${btn(completed?'Lưu chỉnh sửa ✓':'✓ Hoàn thành buổi tập','finish-session','btn primary')}${completed?btn('Xóa buổi tập','delete-session','btn danger'):''}</div><p class="muted-sm">Khi lưu, lịch tuần tự tính lại; những buổi cardio khác cũng thay thế được buổi treadmill. Nhật ký chỉ lưu trên thiết bị.</p></div></div></div>
 <div class="stack"><div class="timer-box"><div class="eyebrow">${cardio?'ĐỒNG HỒ NHỊP / NGHỈ':'ĐỒNG HỒ NGHỈ SET'}</div><div class="timer-value" id="timerValue">${formatTimer(timerLeft)}</div><div class="buttonrow">${btn('30 giây','set-timer','btn small',`data-seconds="30"`)}${btn('60 giây','timer60','btn small')}${btn('90 giây','timer90','btn small')}${btn('Dừng','timerstop','btn small outline')}</div><div class="smallprint">Đây là đồng hồ nghỉ, không thay thế đồng hồ cardio theo thời gian thực.</div></div><div class="panel"><h3>Hướng dẫn phục hồi</h3><p class="muted-sm" style="margin-top:10px">${cardio?'Đừng cố tập HIIT để bù thời gian. Ưu tiên mức vừa, tăng thời lượng mỗi khi đã quen.':'Sau buổi tạ, nghỉ khoảng 48 giờ trước buổi Full Body tiếp theo; vận động nhẹ trong ngày nghỉ.'}</p></div>${healthNote()}</div></div>`;
}
function formatTimer(sec){const v=Math.max(0,sec);return `${String(Math.floor(v/60)).padStart(2,'0')}:${String(v%60).padStart(2,'0')}`;}
function stopTimer(){if(timerHandle)clearInterval(timerHandle);timerHandle=null;timerLeft=0;const e=$('#timerValue');if(e)e.textContent='00:00';}
function startTimer(sec){stopTimer();timerLeft=sec;timerStart=Date.now();const node=$('#timerValue');if(node)node.textContent=formatTimer(sec);timerHandle=setInterval(()=>{timerLeft=Math.max(0,sec-Math.floor((Date.now()-timerStart)/1000));const e=$('#timerValue');if(e)e.textContent=formatTimer(timerLeft);if(timerLeft===0){clearInterval(timerHandle);timerHandle=null;toast('Đã hết giờ nghỉ. Bạn có thể bắt đầu set tiếp theo.');}},250);}
function history(){const logs=Object.entries(state.logs).filter(([,x])=>x?.completed).sort((a,b)=>b[0].localeCompare(a[0]));return `${title('LỊCH SỬ TẬP LUYỆN','Nhật ký của bạn','Mỗi buổi được lưu cùng set, rep, mức tạ, thay thế bài và ghi chú. Có thể mở lại để sửa.')}${logs.length?`<div class="list-log">${logs.map(([date,x])=>`<div class="log-item"><div class="log-item-inner"><div class="log-icon">${SESSIONS[x.type]?.icon||'✓'}</div><div><h3>${esc(sessionName(x.type))} <span class="chip green">✓</span></h3><p>${esc(dateTitle(date))} · ${esc(x.minutes||'—')} phút${x.type==='C'?` · ${esc(x.speed||'—')} km/h · dốc ${esc(x.incline||0)}%`:''}${isCardio(x.type)?` · RPE ${esc(x.effort??'—')}/10`:''}</p>${x.notes?`<p>${esc(x.notes)}</p>`:''}</div></div>${btn('Chi tiết','open-workout','btn small',`data-date="${date}" data-type="${x.type}"`)}</div>`).join('')}</div>`:'<div class="empty"><span class="bigemoji">📓</span><h3>Chưa có buổi nào</h3><p>Hoàn thành buổi tập đầu tiên, nhật ký sẽ xuất hiện ở đây. Không cần hoàn hảo mới được ghi nhận.</p></div>'}`;}
function weightChart(){const points=[...state.weights].sort((a,b)=>a.date.localeCompare(b.date)).slice(-16);if(points.length<2)return '<div class="empty"><h3>Chưa đủ lần cân</h3><p>Ghi ít nhất 2 lần cân để thấy xu hướng. Cân vào cùng thời điểm trong ngày, khoảng 1 lần/tuần.</p></div>';const vals=points.map(x=>Number(x.weight)),min=Math.min(...vals)-.8,max=Math.max(...vals)+.8;const coords=vals.map((v,i)=>({x:25+i*(520/(vals.length-1)),y:190-(v-min)/(max-min)*150}));return `<svg class="weight-plot" viewBox="0 0 570 230" role="img" aria-label="Biểu đồ cân nặng từ ${esc(points[0].date)} đến ${esc(points.at(-1).date)}"><line class="gridline" x1="20" x2="550" y1="40" y2="40"/><line class="gridline" x1="20" x2="550" y1="115" y2="115"/><line class="gridline" x1="20" x2="550" y1="190" y2="190"/><polyline class="line" points="${coords.map(p=>`${p.x},${p.y}`).join(' ')}"/>${coords.map((p,i)=>`<circle cx="${p.x}" cy="${p.y}" r="4"/><text x="${p.x}" y="${p.y-11}" text-anchor="middle">${esc(vals[i])}</text>`).join('')}<text x="25" y="222">${niceDate(points[0].date)}</text><text x="545" y="222" text-anchor="end">${niceDate(points.at(-1).date)}</text></svg>`;}
function insights(){const counts=Array.from({length:8},(_,i)=>{const w=move(monday(today()),(i-7)*7);return {start:w,n:Object.entries(state.logs).filter(([d,v])=>v?.completed && d>=w && d<=move(w,6)).length};});const max=Math.max(3,...counts.map(x=>x.n));const stats=weeklyStats(state.logs,today());return `${title('DỮ LIỆU TIẾN BỘ','Thấy rõ từng thay đổi','Không chỉ theo cân nặng: đánh giá bằng thói quen, sức mạnh và cảm giác tập.')}
<div class="metric-grid"><div class="metric"><div class="metric-top">TỔNG BUỔI</div><div class="metric-value">${stats.total}</div></div><div class="metric"><div class="metric-top">BUỔI TẠ (GỒM CHUYÊN CƠ)</div><div class="metric-value">${stats.strength}</div></div><div class="metric"><div class="metric-top">CARDIO / TỔNG PHÚT</div><div class="metric-value">${stats.cardio} <span class="muted-sm">/ ${stats.cardioMinutes}′</span></div></div></div><div class="insights-grid"><div class="stack"><div class="panel"><h2>Thói quen 8 tuần qua</h2><p class="muted-sm" style="margin:5px 0 26px">Số buổi hoàn thành mỗi tuần, mục tiêu cơ bản 2 buổi sức mạnh + 1 cardio</p><div class="bar-chart">${counts.map(w=>`<div class="bar-wrap"><div class="bar ${w.n>=3?'good':''}" style="height:${Math.max(2,w.n/max*100)}%">${w.n?`<div class="bar-label">${w.n}</div>`:''}</div><small>${niceDate(w.start)}</small></div>`).join('')}</div></div><div class="panel"><div class="panel-heading"><h2>Xu hướng cân nặng</h2><span class="chip">Mục tiêu: ${esc(state.settings.targetWeight)} kg</span></div>${weightChart()}</div></div><div class="stack"><div class="panel"><h2>Ghi cân nặng</h2><p class="muted-sm" style="margin:7px 0 18px">Một lần mỗi tuần là đủ; tránh bị ảnh hưởng bởi dao động nước hàng ngày.</p><div class="form-grid"><label class="form-label">Ngày cân<input id="weightDate" type="date" class="field" value="${today()}"></label><label class="form-label">Cân nặng (kg)<input id="weightValue" type="number" step="0.1" min="20" max="300" class="field" placeholder="73,2"></label><label class="form-label">Vòng eo (cm) – tùy chọn<input id="waistValue" type="number" step="0.1" min="30" max="200" class="field" placeholder="Ví dụ 86"></label></div><div class="buttonrow" style="margin-top:14px">${btn('Lưu chỉ số','save-weight','btn primary')}</div></div><div class="panel"><h3>Thành công không chỉ là cân nặng</h3><p class="muted-sm" style="margin-top:8px">Ưu tiên tăng số buổi duy trì, thực hiện động tác chắc hơn và nâng tạ dần. Nếu muốn hỗ trợ sinh sản, chăm sóc giấc ngủ, lối sống và khám chuyên khoa khi cần quan trọng hơn việc chạy theo mốc cân.</p></div></div></div>`;}
function settings(){return `${title('THIẾT LẬP','Cài đặt & dữ liệu','Thông tin chỉ lưu trong trình duyệt trên thiết bị này, không gửi về máy chủ.')}
<div class="insights-grid"><div class="stack"><div class="panel"><h2>Thông tin mục tiêu</h2><div class="form-grid" style="margin-top:19px"><label class="form-label">Tên hiển thị (tùy chọn)<input id="settingName" class="field" value="${esc(state.settings.nickname)}" maxlength="32" placeholder="Khai Trí hoặc Henry"></label><label class="form-label">Chiều cao (cm)<input id="settingHeight" type="number" class="field" min="120" max="230" value="${esc(state.settings.height)}"></label><label class="form-label">Cân nặng ban đầu (kg)<input id="settingStartWeight" type="number" class="field" min="20" max="300" step="0.1" value="${esc(state.settings.startWeight)}"></label><label class="form-label">Cân nặng tham khảo (kg)<input id="settingTargetWeight" type="number" class="field" min="20" max="300" step="0.1" value="${esc(state.settings.targetWeight)}"></label></div><p class="muted-sm" style="margin-top:10px">Mốc cân nặng là tham khảo; không áp dụng chế độ ăn cực đoan. Tập luyện không thay thế đánh giá hiếm muộn nếu đang có khó khăn thụ thai.</p><div class="divider"></div><h3>Giao diện & màu sắc</h3><p class="muted-sm" style="margin:8px 0 14px">Đổi toàn bộ accent color của app mà không ảnh hưởng dữ liệu tập luyện.</p><div class="theme-grid">${Object.entries(THEMES).map(([id,theme])=>`<button type="button" class="theme-card ${state.settings.theme===id?'selected':''}" data-action="select-theme" data-theme="${id}"><span class="theme-swatch ${id}"></span><strong>${esc(theme.label)}</strong><small>${id==='lime'?'Mặc định mạnh mẽ':id==='purple'?'Hiện đại, nổi bật':id==='orange'?'Năng lượng, ấm hơn':'Tươi, sáng, sạch'}</small></button>`).join('')}</div><input type="hidden" id="settingTheme" value="${esc(state.settings.theme||'lime')}"><div class="buttonrow" style="margin-top:17px">${btn('Lưu mục tiêu & giao diện','save-settings','btn primary')}</div></div><div class="panel"><h2>Sao lưu & phục hồi dữ liệu</h2><p class="muted-sm" style="margin:8px 0 16px">Dữ liệu gồm nhật ký, cân nặng, set/rep, lịch đã bỏ và ghi chú. Trình duyệt khác/thiết bị khác sẽ không có dữ liệu này nếu bạn chưa nhập bản sao lưu.</p><div class="buttonrow">${btn('↓ Xuất file JSON','export','btn primary')}${btn('↑ Nhập bản sao lưu','import','btn outline')}</div><div class="divider"></div><div class="settings-note"><b>Quyền riêng tư:</b> web app không gửi hoặc nhúng PDF/X-quang của bạn lên hosting. Dữ liệu được lưu trong localStorage của trình duyệt. Xóa dữ liệu trình duyệt có thể mất nhật ký; nên xuất sao lưu hàng tuần.</div><div class="buttonrow" style="margin-top:16px">${btn('Xóa toàn bộ dữ liệu thiết bị','reset','btn danger small')}</div></div></div><div class="stack">${healthNote()}<div class="panel"><h3>Nguồn hướng dẫn & video</h3><p class="muted-sm" style="margin:6px 0 16px">Video mở từ trang/YouTube của bên thứ ba, cần Internet. Nội dung hướng dẫn được diễn giải ngắn gọn, không thay thế HLV trực tiếp.</p><div class="resource-list">${RESOURCES.map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.label)} <span>↗</span></a>`).join('')}</div></div><div class="panel"><h3>Cài ứng dụng lên điện thoại</h3><p class="muted-sm" style="margin:9px 0">Android: Chrome → menu ⋮ → Cài đặt ứng dụng / Thêm vào màn hình chính.</p><p class="muted-sm">iPhone: Safari → Chia sẻ → Thêm vào Màn hình chính.</p><div class="smallprint">PWA chỉ cài sau khi website chạy qua HTTPS. Truy cập offline được phần app đã cache; video ngoài vẫn cần mạng.</div></div></div></div>`;}

function openDay(date){const plan=getPlan(monday(date)),day=plan.days.find(d=>d.date===date);if(day?.kind==='done'){setRoute('workout',{date,type:day.type});return;}
 const baseChoices=`<div class="buttonrow" style="margin-top:15px">${['A','B','C'].map(type=>btn(`${SESSIONS[type].icon} ${sessionName(type)}`,'choose-session','btn',`data-date="${date}" data-type="${type}"`)).join('')}</div>`;
 const cardioChoices=`<div class="focus-choice-grid">${Object.entries(SESSIONS).filter(([id])=>isCardio(id)&&id!=='C').map(([id,s])=>btn(`${s.icon} ${s.name}`,'choose-session','btn outline',`data-date="${date}" data-type="${id}"`)).join('')}</div>`;
 const focusChoices=`<div class="focus-choice-grid">${Object.entries(SESSIONS).filter(([id,s])=>s.groupId).map(([id,s])=>btn(`${s.icon} ${s.name}`,'choose-session','btn outline',`data-date="${date}" data-type="${id}"`)).join('')}</div>`;
 const gap=Object.entries(state.logs).filter(([d,x])=>x?.completed&&isStrength(x.type)&&Math.abs(delta(date,d))<2&&d!==date).length;
 modal(`<h2>${dateTitle(date)}</h2><p>Chọn buổi được gợi ý hoặc tập tập trung một nhóm cơ. Lịch tự điều chỉnh dựa trên buổi bạn <b>thực sự hoàn thành</b>.</p>${gap?'<div class="callout health-warning"><b>⚠ Ngày sát buổi tạ khác</b>Có buổi sức mạnh trong vòng 48 giờ; nên ưu tiên hồi phục hoặc chuyển lịch, không tập lại nhóm cơ đang đau.</div>':''}<h3 style="margin-top:17px">Gợi ý cho người mới</h3>${baseChoices}<div class="divider"></div><h3>Cardio: máy, bodyweight & dụng cụ</h3>${cardioChoices}<div class="divider"></div><h3>Tập chuyên một nhóm cơ</h3>${focusChoices}<div class="buttonrow">${btn('Bỏ ngày này','skip-day','btn danger',`data-date="${date}"`)}${btn('Đóng','modal-close','btn outline')}</div>`);}
function modal(html){closeModal();const overlay=document.createElement('div');overlay.className='modal-backdrop';overlay.id='activeModal';overlay.innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-label="Thao tác lịch tập">${html}</div>`;document.body.appendChild(overlay);overlay.addEventListener('click',event=>{if(event.target===overlay)closeModal();});}
function closeModal(){document.querySelector('#activeModal')?.remove();}
function submitWorkout(){const d=draftFor(workoutDate,workoutType),done=Object.values(d.exercises).reduce((sum,x)=>sum+(x.sets||[]).filter(s=>s.done).length,0);if(isCardio(workoutType) && (!Number.isFinite(Number(d.minutes)) || Number(d.minutes)<1 || Number(d.minutes)>240)){toast('Thời lượng cardio phải từ 1 đến 240 phút.');return;}if(!isCardio(workoutType)&&done===0&&!state.logs[workoutDate]?.completed){modal(`<h2>Chưa tick set nào</h2><p>Bạn chưa đánh dấu set tập. Vẫn ghi nhận hoàn thành buổi này?</p><div class="buttonrow">${btn('Lưu dù chưa tick','finish-confirm','btn primary')}${btn('Tiếp tục ghi set','modal-close','btn outline')}</div>`);return;}saveWorkout();}
function saveWorkout(){if(workoutDate>today()){closeModal();toast('Chưa thể ghi nhận hoàn thành một ngày trong tương lai.');return;}const d=draftFor(workoutDate,workoutType);state.logs[workoutDate]={...JSON.parse(JSON.stringify(d)),completed:true,type:workoutType,date:workoutDate,updatedAt:new Date().toISOString()};delete state.skips[workoutDate];save();stopTimer();closeModal();weekStart=monday(workoutDate);toast('✓ Đã lưu buổi tập. Lịch tuần đã tự điều chỉnh.');setRoute('week',{week:weekStart});}
function captureDraftField(target){if(route!=='workout'||!workoutDate||!workoutType)return;const draft=draftFor(workoutDate,workoutType);if(target.matches('[data-cardio-check]')){const id=target.dataset.cardioCheck;if(!draft.exerciseIds.includes(id))return;draft.cardioChecked=target.checked?[...new Set([...draft.cardioChecked,id])]:draft.cardioChecked.filter(x=>x!==id);const badge=$('#checkedSets');if(badge)badge.textContent=draft.cardioChecked.length+' bài đã tick';}else if(target.matches('[data-set]')){const base=target.dataset.set,index=Number(target.dataset.index),field=target.dataset.field;const item=getExerciseDraft(draft,base,workoutDate);if(!item.sets[index])return;item.sets[index][field]=field==='done'?target.checked:target.value;if(field==='done'){target.closest('.set-grid')?.classList.toggle('checked',target.checked);const badge=$('#checkedSets');if(badge)badge.textContent=Object.values(draft.exercises).reduce((sum,x)=>sum+(x.sets||[]).filter(z=>z.done).length,0)+' set đã tick';}}else if(target.matches('[data-swap]')){const base=target.dataset.swap,replacement=target.value;const item=getExerciseDraft(draft,base,workoutDate);if(![base,...EXERCISES[base].alternatives].includes(replacement))return;item.replacement=replacement;item.sets=defaultSets(replacement,workoutDate);save();render();return;}else if(target.id==='cardioMinutes'||target.id==='sessionMinutes')draft.minutes=safeNumber(target.value,0);else if(target.id==='cardioSpeed')draft.speed=safeNumber(target.value,0);else if(target.id==='cardioIncline')draft.incline=safeNumber(target.value,0);else if(target.id==='cardioResistance')draft.resistance=target.value;else if(target.id==='cardioStrokes')draft.strokes=target.value;else if(target.id==='cardioRounds')draft.rounds=Math.min(8,Math.max(1,safeNumber(target.value,2)));else if(target.id==='cardioWork')draft.workSec=Math.min(180,Math.max(15,safeNumber(target.value,40)));else if(target.id==='cardioRest')draft.restSec=Math.min(180,Math.max(10,safeNumber(target.value,20)));else if(target.id==='effort')draft.effort=safeNumber(target.value,0);else if(target.id==='sessionNotes')draft.notes=target.value;else return;save();}
function exportData(){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`gymos-backup-${today()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã tạo bản sao lưu JSON.');}
function render(){document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===route||(route==='exercise'&&b.dataset.nav==='library')||(route==='workout'&&b.dataset.nav==='week')));$('#app').innerHTML=({home,week,cardio,library,exercise:exercisePage,workout,history,insights,settings}[route]||home)();}

// Navigation and actions use event delegation so re-rendered controls work without re-binding.
document.addEventListener('click',event=>{
  const nav=event.target.closest('[data-nav]');if(nav){closeModal();stopTimer();setRoute(nav.dataset.nav);return;}
  const btnEl=event.target.closest('[data-action]');if(!btnEl)return;
  const a=btnEl.dataset.action,date=btnEl.dataset.date,type=btnEl.dataset.type;
  if(a==='cycle-theme'){const choices=Object.keys(THEMES);const idx=choices.indexOf(state.settings.theme||'lime');const next=choices[(idx+1)%choices.length];state.settings.theme=next;applyTheme(next);save();if(route==='settings')render();toast('Đã chuyển sang '+THEMES[next].label);return;}
  if(a==='go-week'){setRoute('week',{week:monday(today())});return;}
  if(a==='go-library'){setRoute('library');return;}
  if(a==='go-cardio'){setRoute('cardio');return;}
  if(a==='go-cardio-library'){exerciseFilter='cardio';setRoute('library');return;}
  if(a==='cardio-filter'){cardioFilter=btnEl.dataset.filter;render();return;}
  if(a==='start-cardio'){if(state.logs[today()]?.completed){toast('Hôm nay đã có một buổi hoàn thành. Vào lịch tuần để chọn ngày khác.');setRoute('week');return;}closeModal();stopTimer();setRoute('workout',{date:today(),type});return;}
  if(a==='week-prev'){weekStart=move(weekStart,-7);render();return;}
  if(a==='week-next'){weekStart=move(weekStart,7);render();return;}
  if(a==='week-current'){weekStart=monday(today());render();return;}
  if(a==='filter'){exerciseFilter=btnEl.dataset.filter;render();return;}
  if(a==='add-cardio'){if(route!=='workout'||!isCardio(workoutType))return;const id=$('#addCardioSelect')?.value,d=draftFor(workoutDate,workoutType);if(!EXERCISES[id]||EXERCISES[id].group!=='Tim mạch'){toast('Chọn bài cardio hợp lệ.');return;}if(d.exerciseIds.length>=6){toast('Tối đa 6 bài cardio trong một buổi.');return;}if(!d.exerciseIds.includes(id)){d.exerciseIds.push(id);save();render();toast('Đã thêm '+EXERCISES[id].vi);}return;}
  if(a==='remove-cardio'){if(route!=='workout'||!isCardio(workoutType))return;const id=btnEl.dataset.exercise,d=draftFor(workoutDate,workoutType);if(d.exerciseIds.length<=1){toast('Giữ ít nhất một bài cardio mỗi buổi.');return;}d.exerciseIds=d.exerciseIds.filter(x=>x!==id);d.cardioChecked=d.cardioChecked.filter(x=>x!==id);save();render();return;}
  if(a==='add-exercise'){if(route!=='workout'||workoutType==='C')return;const id=$('#addExerciseSelect')?.value,d=draftFor(workoutDate,workoutType);if(!EXERCISES[id]){toast('Hãy chọn bài muốn thêm.');return;}if(d.exerciseIds.length>=8){toast('Tối đa 8 bài/buổi; nên tập 4–6 bài nếu mới bắt đầu.');return;}if(!d.exerciseIds.includes(id)){d.exerciseIds.push(id);save();render();toast('Đã thêm '+EXERCISES[id].vi);}return;}
  if(a==='remove-exercise'){if(route!=='workout'||workoutType==='C')return;const id=btnEl.dataset.exercise,d=draftFor(workoutDate,workoutType);if(d.exerciseIds.length<=1){toast('Buổi tập cần ít nhất một bài.');return;}d.exerciseIds=d.exerciseIds.filter(x=>x!==id);delete d.exercises[id];save();render();toast('Đã bỏ bài khỏi buổi này.');return;}
  if(a==='exercise'){setRoute('exercise',{exercise:btnEl.dataset.exercise});return;}
  if(a==='day'){openDay(date);return;}
  if(a==='choose-session'){closeModal();stopTimer();setRoute('workout',{date,type});return;}
  if(a==='open-workout'){closeModal();stopTimer();setRoute('workout',{date,type});return;}
  if(a==='skip-day'){if(state.logs[date]?.completed){toast('Không thể bỏ ngày đã hoàn thành; hãy xóa nhật ký trước.');closeModal();return;}state.skips[date]=true;delete state.drafts[date];save();closeModal();toast('Đã bỏ ngày '+niceDate(date)+'. Lịch đã tính lại.');render();return;}
  if(a==='undo-skip'){delete state.skips[date];save();toast('Đã khôi phục ngày '+niceDate(date));render();return;}
  if(a==='timer60'||a==='timer90'||a==='set-timer'){startTimer(a==='timer60'?60:a==='timer90'?90:Number(btnEl.dataset.seconds)||60);return;}
  if(a==='timerstop'){stopTimer();return;}
  if(a==='finish-session'){submitWorkout();return;}
  if(a==='finish-confirm'){saveWorkout();return;}
  if(a==='delete-session'){modal(`<h2>Xóa buổi đã tập?</h2><p>Xóa nhật ký ngày ${niceDate(workoutDate)} và cho lịch tính lại. Không thể khôi phục nếu không có bản sao lưu.</p><div class="buttonrow">${btn('Xóa buổi này','delete-confirm','btn danger')}${btn('Hủy','modal-close','btn outline')}</div>`);return;}
  if(a==='delete-confirm'){delete state.logs[workoutDate];delete state.drafts[workoutDate];save();stopTimer();closeModal();toast('Đã xóa buổi tập.');setRoute('week',{week:monday(workoutDate)});return;}
  if(a==='modal-close'){closeModal();return;}
  if(a==='save-weight'){const date=$('#weightDate').value,weight=Number($('#weightValue').value),waist=$('#waistValue').value;if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(weight)||weight<20||weight>300){toast('Hãy nhập ngày và cân nặng hợp lệ.');return;}state.weights=state.weights.filter(x=>x.date!==date);state.weights.push({date,weight,waist:waist?Number(waist):null});state.weights.sort((a,b)=>a.date.localeCompare(b.date));save();toast('Đã lưu cân nặng.');render();return;}
  if(a==='select-theme'){const theme=btnEl.dataset.theme;if(!THEMES[theme])return;$('#settingTheme') && ($('#settingTheme').value=theme);document.querySelectorAll('.theme-card').forEach(el=>el.classList.toggle('selected',el.dataset.theme===theme));applyTheme(theme);return;}
  if(a==='save-settings'){const height=Number($('#settingHeight').value),start=Number($('#settingStartWeight').value),target=Number($('#settingTargetWeight').value),theme=($('#settingTheme')?.value||'lime');if(height<120||height>230||start<20||start>300||target<20||target>300){toast('Hãy kiểm tra số đo đã nhập.');return;}state.settings={...state.settings,nickname:$('#settingName').value.slice(0,32),height,startWeight:start,targetWeight:target,theme:THEMES[theme]?theme:'lime'};applyTheme(state.settings.theme);save();toast('Đã lưu mục tiêu và giao diện.');render();return;}
  if(a==='export'){exportData();return;}
  if(a==='import'){$('#importFile').click();return;}
  if(a==='reset'){modal(`<h2>Xóa tất cả nhật ký?</h2><p>Dữ liệu trên thiết bị này sẽ mất. Nên xuất bản sao lưu trước.</p><div class="buttonrow">${btn('Xóa toàn bộ','reset-confirm','btn danger')}${btn('Hủy','modal-close','btn outline')}</div>`);return;}
  if(a==='reset-confirm'){state=initial();applyTheme(state.settings.theme);save();closeModal();weekStart=monday(today());route='home';render();toast('Đã đặt lại dữ liệu thiết bị.');return;}
});
document.addEventListener('change',event=>captureDraftField(event.target));
document.addEventListener('input',event=>{if(event.target.id==='exerciseSearch'){exerciseQuery=event.target.value;const focus=event.target.selectionStart;render();const input=$('#exerciseSearch');input.focus();input.setSelectionRange(focus,focus);return;}if(event.target.id==='sessionNotes')captureDraftField(event.target);});
$('#importFile').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{const incoming=JSON.parse(await f.text());if(!incoming||typeof incoming!=='object'||incoming.version!==1||!incoming.logs||!incoming.settings||!incoming.skips||!Array.isArray(incoming.weights))throw Error('Sai định dạng sao lưu.');modal(`<h2>Nhập bản sao lưu?</h2><p>File chứa ${Object.values(incoming.logs).filter(x=>x.completed).length} buổi tập. Thao tác này <b>thay thế toàn bộ dữ liệu hiện tại</b>.</p><div class="buttonrow">${btn('Nhập và thay thế','import-confirm','btn primary')}${btn('Hủy','modal-close','btn outline')}</div>`);promptModal=incoming;}catch{toast('Không đọc được file JSON GymOS hợp lệ.');}e.target.value='';});
document.addEventListener('click',e=>{if(e.target.closest('[data-action="import-confirm"]')){if(promptModal){state={...initial(),...promptModal,settings:{...initial().settings,...promptModal.settings},logs:promptModal.logs||{},skips:promptModal.skips||{},drafts:promptModal.drafts||{},weights:promptModal.weights||[]};applyTheme(state.settings.theme);save();promptModal=null;closeModal();setRoute('home');toast('Đã nhập bản sao lưu thành công.');}}});
window.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
if('serviceWorker' in navigator && (location.protocol==='https:'||location.hostname==='localhost'||location.hostname==='127.0.0.1'))window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
applyTheme(state.settings.theme);
render();
